// friday13.cs — Friday the 13th explorer (proleptic Gregorian)

// Find the earliest Friday the 13th starting from 0001-01-01
DateTime? earliest = null;
for (int year = 1; year <= 9999 && earliest is null; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        var d = new DateTime(year, month, 13);
        if (d.DayOfWeek == DayOfWeek.Friday)
        {
            earliest = d;
            break;
        }
    }
}
Console.WriteLine($"Earliest Friday the 13th: {earliest:yyyy-MM-dd} ({earliest:dddd})");

// Count Friday the 13ths in a full 400-year Gregorian cycle (years 1–400)
int count = 0;
for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        if (new DateTime(year, month, 13).DayOfWeek == DayOfWeek.Friday)
            count++;
    }
}
Console.WriteLine($"Friday the 13ths in a 400-year cycle: {count}");
Console.WriteLine($"Average per year: {count / 400.0:F4}");

// Bonus: distribution by month across the 400-year cycle
Console.WriteLine("\nDistribution by month:");
for (int month = 1; month <= 12; month++)
{
    int mc = 0;
    for (int year = 1; year <= 400; year++)
    {
        if (new DateTime(year, month, 13).DayOfWeek == DayOfWeek.Friday)
            mc++;
    }
    Console.WriteLine($"  {new DateTime(2000, month, 1):MMMM,-12} {mc}");
}

